"""Reader-facing science drawn from the existing notation-audited documents."""
import streamlit as st

def show_methodology():
    st.subheader('Scientific methodology and limitations')
    st.write('A steady, one-dimensional balance resolves hydrogen pressure and temperature along a horizontal, constant-area pipe. The pipeline is not a three-dimensional CFD model.')
    with st.expander('Governing equations and notation',expanded=True):
        st.latex(r'\frac{d(\rho uA)}{dx}=0,\qquad \dot m=\rho uA,\qquad G=\frac{\dot m}{A},\quad A=\frac{\pi D^2}{4}')
        st.latex(r'\frac{dp}{dx}+G\frac{du}{dx}=-F,\qquad F=\frac{f_DG^2}{2D\rho}')
        st.latex(r'\frac{d}{dx}\left(h+\frac{u^2}{2}\right)=\frac{q_{\mathrm{used}}^{\prime}}{\dot m}')
        st.write('Here x and D are distance and inner diameter (m); A is area (m²); ṁ is mass flow (kg/s); G is mass flux (kg/(m² s)); u is velocity (m/s); ρ is density (kg/m³); p is absolute pressure (Pa); h is specific enthalpy (J/kg); f_D is the dimensionless Darcy factor; F is frictional pressure loss per length (Pa/m). Heat q′ is a rate per pipe length (W/m), positive into the gas.')
        st.caption('The kinetic-energy and momentum-acceleration terms are retained together by default. The optional acceleration switch removes both. Friction is already included in total energy; adding a separate Darcy heating source would double-count it.')
        st.latex(r'\rho=\frac{p}{ZRT},\quad c_p=\left(\frac{\partial h}{\partial T}\right)_p,\quad h_p=\left(\frac{\partial h}{\partial p}\right)_T=\frac{1+T\rho_T/\rho}{\rho}')
        st.write('T is temperature (K), R is the specific gas constant (J/(kg K)), Z is compressibility, c_p is heat capacity (J/(kg K)), and ρ_T is the density derivative at fixed pressure. Real modes evaluate density, enthalpy and derivatives using CoolProp HEOS::Hydrogen. Ideal modes use Z = 1 and the same model’s ideal Helmholtz contribution for h and c_p. All four retain HEOS transport properties.')
        st.latex(r'\begin{bmatrix}1-u^2\rho_p&-u^2\rho_T\\h_p-u^2\rho_p/\rho&c_p-u^2\rho_T/\rho\end{bmatrix}\begin{bmatrix}dp/dx\\dT/dx\end{bmatrix}=\begin{bmatrix}-F\\q_{\mathrm{used}}^{\prime}/\dot m\end{bmatrix}')
        st.caption('ρ_p denotes the density derivative at fixed temperature. This is the coupled gas ODE system, not a finite-element solid-conduction calculation.')
    with st.expander('Friction and hydrogen-to-soil heat transfer'):
        st.latex(r'\frac{1}{\sqrt{f_D}}=-2\log_{10}\left(\frac{\epsilon}{3.7D}+\frac{2.51}{\mathrm{Re}\sqrt{f_D}}\right),\qquad \mathrm{Re}=\frac{GD}{\mu}')
        st.latex(r'q_{\mathrm{ground}}^{\prime}=\frac{T_\infty-T}{\mathcal R},\quad \mathcal R=\frac{1}{h_i\pi D}+\frac{\ln(r_o/r_i)}{2\pi k_w}+\frac{\operatorname{acosh}(H_b/r_o)}{2\pi k_s}')
        st.write('ε is equivalent sand-grain roughness (m), μ is viscosity (Pa s), r_i = D/2 and r_o = r_i + wall thickness (m), H_b is centreline burial depth (m), h_i is gas-film conductance (W/(m² K)), k_w and k_s are wall and soil conductivities (W/(m K)), and T∞ is prescribed soil temperature (K). Resistance per length has units K m/W. Colebrook or Haaland provides Darcy friction; Gnielinski or Dittus–Boelter provides the internal film coefficient.')
        st.write('Coupled models use ground heat in the energy balance. Isothermal models impose constant T, infer required heat, and report thermostat duty q′_th = q′_used − q′_ground. “Adiabatic environment” sets ground heat to zero; an imposed-isothermal model may still require a thermostat.')
    with st.expander('Numerical method, convergence and conservation'):
        st.write('SciPy DOP853 integrates normalized pressure and temperature with relative tolerance 2×10⁻⁸, absolute tolerance 2×10⁻¹¹ on normalized variables, dense output, and maximum axial step L/40. Forward/comparison profiles use 801 uniform audit locations; these sample the adaptive solution and do not form a physical mesh. The delivery inverse uses the package’s 201-point final audit and Brent root search. There is no physical gas time step.')
        st.write('Returned solutions must reach the full pipe length without a terminal pressure or Mach event. Simpson quadrature independently checks integrated momentum and total energy. Relative residual denominators use the documented pressure-drop and energy scales with floors of 1 Pa and 1 J/kg. Mass consistency is algebraic because u = G/ρ.')
        st.write('The retained project checks include an ideal-isothermal analytical pressure solution, a separately formulated conservative midpoint solver, matched pandapipes hydraulics, property identities and compressor work integration. These are numerical verification. Agreement with shared constitutive assumptions does not validate physical accuracy. The separate P1 finite-element/backward-Euler solid benchmark is not exposed as a transient hydrogen simulation.')
    with st.expander('Admissibility and public-service limits'):
        st.write('Solved gas states must remain between 200 and 500 K, above the minimum pressure of 0.1 MPa, and at or below 30 MPa. Mach must remain below 0.8; critical-state guards can stop integration sooner. Burial depth exceeds outside radius and relative roughness is at most 0.05. These are software restrictions, not calibrated design or safety ranges.')
        st.write('Laminar friction and Nu = 3.66 apply below Re = 2300. Transitional flow is rejected. Turbulent Gnielinski requires Re = 4000–5×10⁶ and Pr = 0.5–2000; Dittus–Boelter requires Re = 10⁴–5×10⁶ and Pr = 0.6–160. The solver checks these along the trajectory. Environmental heat-transfer guards are bypassed only when heat exchange is explicitly disabled.')
        st.write('This hosted interface additionally bounds input magnitudes, admits one numerical job per server process, limits run duration, and spaces requests. A time-limit or capacity failure is a web-service limit, not a claim of physical infeasibility. No invalid input is silently adjusted.')
    st.warning('Research and educational use only. H2PipeBench is a scientific numerical simulation tool. Its predictions are not certified for industrial pipeline design, safety assessments, equipment selection or regulatory compliance.')
    st.write('Full-scale experimental hydrogen-pipeline accuracy has not been established. Published laboratory-loop comparisons remain partly unresolved, with incomplete boundary conditions and metrology. Small numerical residuals do not remove these discrepancies. No structural, material compatibility, embrittlement, equipment-rating or regulatory conclusion is supported.')
